-- Lesson order follows the Metanit Rust tutorial table of contents.
INSERT INTO courses (id, owner, language, title, description, published)
VALUES ('e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'RUST', 'Основы Rust', 'Синтаксис Rust, составные типы, владение, заимствование, методы и трейты. Краткие конспекты со ссылками на учебник Metanit.', TRUE);

INSERT INTO course_modules (id, course_id, title, position) VALUES
    ('4bd28533-5829-56ea-ae3b-d6a53115bf5d', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'Введение в Rust', 0),
    ('62466c02-e999-5a2f-b6c0-36ce9b959afc', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'Основы Rust', 1),
    ('bb62cdb2-d23c-55ba-b813-ebaf99015ed6', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'Составные типы данных', 2),
    ('b947073d-ba8e-593f-91da-18a0c6db35f1', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'Ссылки и владение', 3),
    ('3a23fea7-4429-5650-a7e9-f890c99c6571', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'Методы, трейты и обобщения', 4);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('971307ac-f706-549e-a19d-037482d8c82a', '4bd28533-5829-56ea-ae3b-d6a53115bf5d', 'Возможности Rust и установка',
     $lesson$Rust компилируется в машинный код. Система владения и заимствования позволяет проверять безопасность работы с памятью во время компиляции. Для установки инструментария используйте rustup. После установки проверьте команды rustc --version и cargo --version: первая проверяет компилятор, вторая — менеджер проектов.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/1.1.php)$lesson$, 0),
    ('36d0a06a-ee8b-5c40-956b-02230bed08f7', '4bd28533-5829-56ea-ae3b-d6a53115bf5d', 'Первая программа и её запуск',
     $lesson$Создайте файл main.rs и объявите функцию fn main(). Вызов println!("Привет, Rust!") выведет строку с переводом строки. Команда rustc main.rs создаёт исполняемый файл. Для проекта Cargo можно выполнить cargo new hello, перейти в каталог hello и запустить cargo run.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/1.2.php)$lesson$, 1);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('8a49b83d-e6cb-5013-85f6-5a40b519a714', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Структура исходной программы',
     $lesson$В обычном исполняемом крейте программа начинает работу с main. Исходный файл может содержать определения функций, типов и модулей. Блоки ограничены фигурными скобками, а комментарий с // продолжается до конца строки. Последнее выражение блока может передать значение во внешний код.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.1.php)$lesson$, 0),
    ('5f45abfd-ced6-529b-8c67-e063d14e1e12', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Переменные, mut и затенение',
     $lesson$Объявление let x = 3 создаёт неизменяемую привязку. Для присваивания нового значения используйте let mut x. Второе let x создаёт отдельную привязку с тем же именем и может даже изменить тип, например после разбора введённой строки.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.2.php)$lesson$, 1),
    ('73c7f437-d802-513b-8559-00539df4dbe1', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Простые типы и литералы',
     $lesson$Целые числа имеют знаковые и беззнаковые варианты, например i32 и u32. Тип usize подходит для индексов и размеров, а bool содержит true или false. Литерал 'Я' имеет тип char и представляет один скалярный символ Unicode. Тип может следовать из использования значения или задаваться аннотацией.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.3.php)$lesson$, 2),
    ('2806980c-1bf1-58e5-a528-c46618a8e03a', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Преобразование числовых типов',
     $lesson$Для явного числового преобразования можно написать value as u8. При сужении целого старшие биты отбрасываются, поэтому 300_u16 as u8 даст 44. Если выход за диапазон должен быть ошибкой, используйте TryFrom или TryInto и обработайте Result.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.26.php)$lesson$, 3),
    ('c8f2f780-b909-53aa-81e7-746a5fca6e3b', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Арифметические выражения',
     $lesson$Операторы +, -, *, / и % выполняют обычные арифметические действия. Деление целых 7 / 3 даёт 2, а остаток равен 1. Для вычислений с дробью используйте совместимые вещественные операнды. Методы checked_add и checked_mul возвращают None при переполнении.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.4.php)$lesson$, 4),
    ('df786534-24a1-5bca-aa1e-035600fe9e1a', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Операции над битами',
     $lesson$Операторы &, | и ^ вычисляют И, ИЛИ и исключающее ИЛИ по отдельным битам. Операторы << и >> сдвигают биты. Например, flags & (1 << 2) выделяет третий бит, если считать с нуля. Оператор ! инвертирует все биты целого числа.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.5.php)$lesson$, 5),
    ('39f6b470-428f-5e78-b252-d275757dd73a', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Сравнение и логика',
     $lesson$Сравнения возвращают bool. Операторы && и || вычисляют правый операнд лишь тогда, когда его результат влияет на ответ. Поставьте проверку делителя перед делением, например d != 0 && n / d > 5. Оператор ! меняет логическое значение на противоположное.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.6.php)$lesson$, 6),
    ('30c4a015-7671-5913-827c-e5b38c6127cc', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Ветвление и значение if',
     $lesson$Условие if должно иметь тип bool. Когда if используется для вычисления значения, ветви должны давать совместимые типы. Выражение let sign = if n < 0 { -1 } else { 1 }; присваивает результат выбранной ветви.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.7.php)$lesson$, 7),
    ('cae66bed-1e3a-5633-933a-1e2628b7ea25', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Выбор ветви через match',
     $lesson$match последовательно сравнивает значение с шаблонами и выбирает первую подходящую ветвь. Каждый возможный случай должен быть покрыт. Ветка с _ принимает оставшиеся значения. Результат выбранной ветви можно сохранить в переменной.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.8.php)$lesson$, 8),
    ('13a7c39e-255a-52f1-b9ef-50fdecc9c4df', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Три вида циклов',
     $lesson$loop повторяет тело до break. while проверяет условие перед каждой итерацией. for перебирает элементы значения, которое можно преобразовать в итератор. continue пропускает остаток текущей итерации, а break завершает цикл.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.9.php)$lesson$, 9),
    ('0ef0de48-e8b4-5c44-a8c8-62c4528c08b2', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Определение функции',
     $lesson$Функция начинается с fn. После имени указывают список параметров, при необходимости возвращаемый тип, затем тело. Определение может располагаться ниже места вызова. Небольшие функции упрощают повторное использование вычислений и проверку граничных случаев.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.10.php)$lesson$, 10),
    ('58edb93a-9981-5c77-9970-cc7926a08bb6', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Аргументы и параметры функций',
     $lesson$В объявлении указывают тип каждого параметра, например fn scale(value: i32, factor: i32). При вызове аргументы передаются в порядке объявления. Привязка параметра неизменяема по умолчанию, а поведение переданного значения зависит от его типа и заимствования.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.11.php)$lesson$, 11),
    ('a101b5f6-8d77-563d-8711-7db31d1048aa', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Как функция возвращает результат',
     $lesson$Возвращаемый тип указывается после ->. Последнее выражение тела без точки с запятой образует результат. Для раннего завершения можно написать return expression;. Функция без указанного возвращаемого типа возвращает единичное значение ().

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.12.php)$lesson$, 12),
    ('27fb09eb-1254-531d-8b99-af4bff243eb4', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Константы и их типы',
     $lesson$Константа объявляется с const и явным типом. Её значение вычисляется при компиляции. Именованная константа, например const BUFFER_SIZE: usize = 32, помогает вынести из кода повторяющиеся размеры и пределы.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.13.php)$lesson$, 13),
    ('8f9bf9e7-2898-5ad1-8533-55e2c19497a9', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Замыкание без имени и выражение-блок',
     $lesson$Замыкание |n| n * 2 можно присвоить переменной и вызвать как функцию. Блок { let n = 6; n * 2 } возвращает 12 благодаря последнему выражению. Если поставить после n * 2 точку с запятой, значением блока станет ().

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.20.php)$lesson$, 14),
    ('be19114d-05a0-5dbd-856f-13fdd7e0e4e1', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Захват окружения замыканием',
     $lesson$Замыкание может использовать значения из внешней области видимости. Оно захватывает их через общее или изменяемое заимствование либо по значению, в зависимости от операций в теле. Ключевое слово move захватывает используемые значения по значению, что полезно при передаче замыкания дальше.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.21.php)$lesson$, 15),
    ('5f7853a6-f74c-528c-a65e-48605f36a874', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Указатель на функцию',
     $lesson$Запись fn(i32) -> i32 описывает указатель на вызываемую функцию с одним входным и одним выходным целым числом. Именованную функцию подходящей сигнатуры можно сохранить в такой переменной. К этому типу также приводятся замыкания без захваченных переменных.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.23.php)$lesson$, 16),
    ('eb69a039-9b0e-52cd-94e4-580aed5407bb', '62466c02-e999-5a2f-b6c0-36ce9b959afc', 'Передача и возврат функций',
     $lesson$Параметр типа fn(i32) -> i32 позволяет передать вычисление другой функции. Для замыкания с захваченными значениями используют обобщённый параметр с ограничением Fn, FnMut или FnOnce. Возвращаемое impl Fn описывает вызываемое значение с одним конкретным скрытым типом.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.24.php)$lesson$, 17);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('11ef906d-23ac-514c-a72f-b8ccc299aa37', 'bb62cdb2-d23c-55ba-b813-ebaf99015ed6', 'Кортежи и их распаковка',
     $lesson$Кортеж группирует фиксированное число значений, в том числе разных типов. Элемент можно прочитать по позиции: point.0. Запись let (x, y) = point распаковывает кортеж. Одноэлементный кортеж требует завершающей запятой, например (5,).

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.14.php)$lesson$, 0),
    ('55c2990e-ecff-5aa7-9c4c-79b8487d4522', 'bb62cdb2-d23c-55ba-b813-ebaf99015ed6', 'Массивы фиксированной длины',
     $lesson$Тип [i32; 4] хранит четыре целых числа одного типа. Чтение по индексу начинается с нуля, а выход за границы приводит к ошибке. Запись [0; 4] создаёт массив из четырёх нулей. Если длину нужно менять, используют `Vec<T>`.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.15.php)$lesson$, 1),
    ('08710a7d-f12a-5399-af41-2c646af01ca8', 'bb62cdb2-d23c-55ba-b813-ebaf99015ed6', 'Моделирование данных структурами',
     $lesson$struct объединяет именованные поля. Значение обычно создаётся перечислением полей в фигурных скобках, а доступ к полю выполняется через точку. Подбирайте типы полей так, чтобы структура отражала данные предметной области.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.16.php)$lesson$, 2),
    ('17d16986-2283-5b87-9505-2040324a4cdf', 'bb62cdb2-d23c-55ba-b813-ebaf99015ed6', 'Кортежные структуры и отдельные типы',
     $lesson$У кортежной структуры поля имеют позиции, например struct Meters(u32). К полю обращаются как value.0. Даже если у типов Meters и Seconds одно и то же внутреннее представление, компилятор различает эти типы и не подставит секунды вместо метров.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.17.php)$lesson$, 3),
    ('747c3342-16b4-514f-b174-75247841808f', 'bb62cdb2-d23c-55ba-b813-ebaf99015ed6', 'Перечисления с данными',
     $lesson$enum задаёт набор допустимых вариантов. Вариант может хранить связанные с ним данные, например Some(value) в `Option<T>`. Сопоставление с match позволяет обработать каждую форму и получить полезную нагрузку.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.18.php)$lesson$, 4),
    ('873123ec-1348-532f-9553-c6cddd40677a', 'bb62cdb2-d23c-55ba-b813-ebaf99015ed6', 'Границы диапазонов',
     $lesson$Диапазон 2..5 включает 2, 3 и 4. Запись 2..=5 включает конечное значение 5. Диапазоны применяются в циклах и срезах. Выбирайте форму с учётом того, нужно ли обрабатывать верхнюю границу.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.19.php)$lesson$, 5),
    ('b41cac5c-2d1b-5e21-bd8b-0546096b5d00', 'bb62cdb2-d23c-55ba-b813-ebaf99015ed6', 'Шаблоны, распаковка и условия match',
     $lesson$Шаблон может проверить литерал, распаковать структуру или присвоить части значения имя. Например, ветвь Some(n) if n > 0 подходит только для положительного n. Конструкция _ игнорирует данные или покрывает остальные значения.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.25.php)$lesson$, 6),
    ('4b751aac-c195-5f12-972d-c6ce667a176f', 'bb62cdb2-d23c-55ba-b813-ebaf99015ed6', 'Выбор одного шаблона через if let',
     $lesson$Если важен один вариант, используйте if let Some(value) = candidate и работайте с value в теле условия. Можно добавить else для оставшихся случаев. Для полноценной обработки нескольких вариантов удобен match.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/2.22.php)$lesson$, 7);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('abeb3d5c-a193-55e1-ab96-bae37f793800', 'b947073d-ba8e-593f-91da-18a0c6db35f1', 'Область действия имён',
     $lesson$Имя, объявленное внутри блока, доступно от объявления до конца блока. Вложенный блок видит внешние имена и может затенить их своими привязками. Завершение области видимости влияет на освобождение ресурсов, которыми владеют её локальные значения.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/3.1.php)$lesson$, 0),
    ('49f0f227-d473-584d-a842-7b2b318325c1', 'b947073d-ba8e-593f-91da-18a0c6db35f1', 'Стек, куча и размещение данных',
     $lesson$Локальные значения с известным размером часто размещаются в кадре стека. Данные, размер которых меняется при работе программы, могут находиться в куче. Например, у локальной String поля длины, ёмкости и указателя находятся в самом значении, а выделенный буфер хранится отдельно.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/3.2.php)$lesson$, 1),
    ('fff55784-b491-541d-96ed-b9d51c1b100e', 'b947073d-ba8e-593f-91da-18a0c6db35f1', 'Перемещение и копирование значений',
     $lesson$При присваивании String другому имени владение буфером перемещается, и исходное имя нельзя использовать для доступа к нему. Значения типов с Copy, например i32, при присваивании копируются. Чтобы получить независимую копию String, вызовите clone и учтите стоимость выделения и копирования буфера.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/3.3.php)$lesson$, 2),
    ('d076349a-e472-5547-a6c6-cfec71a5892c', 'b947073d-ba8e-593f-91da-18a0c6db35f1', 'Общее заимствование',
     $lesson$Запись &value создаёт общую ссылку. Функция с параметром &str может прочитать строку, пока владелец сохраняет её. Для доступа к значению действует разыменование *, хотя многие вызовы методов выполняют его автоматически. Компилятор проверяет, что использование ссылки укладывается в срок жизни данных.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/3.4.php)$lesson$, 3),
    ('ad7e7ad9-bcdb-59b0-a52e-b367e1288701', 'b947073d-ba8e-593f-91da-18a0c6db35f1', 'Изменяемое заимствование',
     $lesson$Ссылка &mut позволяет изменять заимствованные данные. Пока такое заимствование активно, одновременно читать те же данные по другой ссылке или брать вторую &mut нельзя. Ограничение относится к пересекающимся заимствованиям и помогает предотвращать неконтролируемые изменения.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/3.5.php)$lesson$, 4),
    ('0dffdf06-22d5-5b89-8ade-7c9f19bcfc51', 'b947073d-ba8e-593f-91da-18a0c6db35f1', 'Владение в замыканиях',
     $lesson$Если тело замыкания только читает переменную, компилятор может захватить общую ссылку. Изменение требует изменяемого заимствования. Когда тело забирает захваченное значение, вызов может быть доступен только через FnOnce. move задаёт захват по значению, а возможность повторного вызова зависит от действий в теле.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/3.7.php)$lesson$, 5);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('d24a3bd6-bb62-59be-b385-2ca656dd9dcd', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Методы и получатель self',
     $lesson$Метод определяется в блоке impl и принимает self в качестве получателя. &self позволяет читать объект, &mut self — менять его, а self передаёт объект по значению. Вызов value.method() выбирает способ передачи получателя по сигнатуре.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.1.php)$lesson$, 0),
    ('4de5cf35-52e3-5b21-8146-d0b7fb0a35ff', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Ассоциированные функции типа',
     $lesson$Функция в impl без параметра self вызывается через имя типа, например Point::new(3, 4). Её удобно использовать для конструирования значений со стандартными настройками или проверками. Имя new — соглашение, и у типа может быть несколько именованных функций создания.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.2.php)$lesson$, 1),
    ('486702c9-8758-521a-a5ea-cbca5bdf35eb', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Общее поведение через trait',
     $lesson$Трейт перечисляет операции, доступные через общий контракт. Тип реализует контракт в блоке impl Trait for Type. Метод трейта может иметь реализацию по умолчанию. Тогда реализация типа может использовать её или заменить своей.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.3.php)$lesson$, 2),
    ('aed47589-107c-58e8-b457-3729f6636f11', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Трейты на входе и выходе функции',
     $lesson$Аргумент &impl Trait принимает ссылку на любой конкретный тип с нужной реализацией. Возврат impl Trait скрывает конкретный тип выбранного значения. Все ветви такой функции должны возвращать один конкретный тип. Для выбора между разными типами во время выполнения можно использовать объект трейта.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.4.php)$lesson$, 3),
    ('8f1080a9-8921-5b3e-99c5-f19671af1262', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Структуры с параметрами типов',
     $lesson$Объявление struct `Pair<T>` позволяет использовать одну структуру с разными конкретными типами. При создании значения параметры обычно выводятся из полей. Если поля могут иметь разные типы, задайте два параметра, например `Pair<T, U>`.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.5.php)$lesson$, 4),
    ('955f8508-1766-5c21-a68f-249506290ee1', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Обобщённые функции и методы',
     $lesson$В fn `identity<T>`(value: T) -> T один параметр T обозначает тип и входа, и результата. Компилятор подставляет конкретный тип при использовании. Метод может использовать параметры impl и объявлять собственные, если часть его входных данных с типом структуры не связана.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.6.php)$lesson$, 5),
    ('d890ff2c-21ba-5d1c-ba06-f81495dad7fa', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Ограничения параметров типов',
     $lesson$Ограничение T: Display даёт право форматировать значение T через {}. Несколько требований можно соединить знаком +. Если параметров и ограничений много, форма where помогает отделить их от основной сигнатуры.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.7.php)$lesson$, 6),
    ('a0769735-6950-558b-8ade-5e1ad714d97c', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Реализация трейта для группы типов',
     $lesson$Обобщённая реализация может автоматически предоставлять трейт всем типам, удовлетворяющим условию. Например, стандартная библиотека предоставляет ToString типам, реализующим Display. Пересекающиеся реализации запрещены, поскольку компилятор должен однозначно выбрать подходящую.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.8.php)$lesson$, 7),
    ('0cd3131a-e9b2-5d8f-89b8-66aba2ab4f65', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Операторы и трейты стандартной библиотеки',
     $lesson$Поведение сложения пользовательских типов определяется трейтом std::ops::Add. Метод add получает операнды, а ассоциированный тип Output задаёт результат. Перегрузка удобна там, где смысл оператора естественен для предметной области, например при сложении двух векторов.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.9.php)$lesson$, 8),
    ('27630e47-9e2a-561c-9b31-ec7bab2d2ea5', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Ассоциированные типы в трейтах',
     $lesson$Реализация трейта с ассоциированным типом выбирает этот тип вместе с остальными деталями контракта. Так, Iterator объявляет Item, и конкретный итератор определяет тип своих элементов. Ограничение `Iterator<Item = i32>` требует, чтобы итератор выдавал значения i32.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.11.php)$lesson$, 9),
    ('0751e721-e96d-5bb8-bd0a-337ab77716ee', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Объекты трейтов и динамический вызов',
     $lesson$Ссылка &dyn Trait или `Box<dyn Trait>` позволяет работать с разными конкретными типами через один интерфейс. Реализация метода выбирается во время выполнения. Чтобы трейт подходил для dyn, его доступные через объект методы должны удовлетворять ограничениям динамической диспетчеризации.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.12.php)$lesson$, 10),
    ('3c5ca371-bec5-539b-9c81-0086438ae852', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Реализация трейта при условии',
     $lesson$Запись `impl<T: Display>` Trait for `Wrapper<T>` добавляет поведение лишь оболочкам, содержимое которых реализует Display. Оболочка `Wrapper<T>` может существовать и без такой реализации. Ограничивать лучше конкретную операцию, которой действительно нужны дополнительные свойства T.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.13.php)$lesson$, 11),
    ('1fe67fe1-d3e6-5cd0-bb0f-8457c84cd40d', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Как типы кодируют состояния',
     $lesson$Разными типами можно выразить стадии работы, например неподготовленное и готовое соединение. Метод перехода потребляет значение первого типа и возвращает второй. Тогда функции, требующие готового состояния, отсекают недопустимые вызовы при компиляции.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.14.php)$lesson$, 12),
    ('348e6c1d-175d-5436-bb7d-7013b44ec09d', '3a23fea7-4429-5650-a7e9-f890c99c6571', 'Форматирование через Debug и Display',
     $lesson$Формат {:?} вызывает Debug и подходит для диагностики. Его часто получают через #[derive(Debug)]. Формат {} вызывает Display, реализацию которого пишут для представления значения читателю. Вывод Display имеет смысл проверять, если его использует интерфейс или условие задачи.

[Metanit — оригинальный урок](https://metanit.com/rust/tutorial/5.15.php)$lesson$, 13);
